mapper.select:
SELECT COUNT(*)
FROM sd_proofing_invitations inv
WHERE inv.invitee_user_id = #{userId}

SELECT COUNT(*)
FROM sd_proofing_invitations inv
WHERE inv.inviter_user_id = #{userId}

SELECT inv.id, inv.work_id, inv.product_title, inv.product_description, inv.model_source, inv.cooperation_content, inv.keywords, inv.is_batch_production, inv.proofing_quantity, inv.delivery_limit_hours, inv.draw_number, inv.created_at, -- 商家自己的报价信息 inv.quoted_price, inv.quoted_period_days, inv.is_quote_batch_plan, inv.quote_submit_at, inv.tiered_pricing, inv.profit_share_ratio, inv.status, CASE WHEN inv.selected_invitee_user_id = #{merchantId} THEN 1 ELSE 0 END AS is_selected, inv.selected_at, -- 邀约人信息 inv.inviter_user_id, inviter.nick_name AS inviter_nick_name, inviter.avatar AS inviter_avatar, inviter.remark AS inviter_description FROM sd_proofing_invitations inv LEFT JOIN sys_user inviter ON inv.inviter_user_id = inviter.user_id WHERE inv.invitee_user_id = #{merchantId}
AND inv.status = #{status}
ORDER BY inv.created_at DESC

SELECT inv.id, inv.work_id, inv.product_title, inv.product_description, inv.model_source, inv.cooperation_content, inv.keywords, inv.is_batch_production, inv.proofing_quantity, inv.delivery_limit_hours, inv.draw_number, inv.created_at, -- 商家自己的报价信息 inv.quoted_price, inv.quoted_period_days, inv.is_quote_batch_plan, inv.quote_submit_at, inv.tiered_pricing, inv.profit_share_ratio, inv.status, CASE WHEN inv.selected_invitee_user_id = #{merchantId} THEN 1 ELSE 0 END AS is_selected, inv.selected_at, -- 邀约人信息 inv.inviter_user_id, inviter.nick_name AS inviter_nick_name, inviter.avatar AS inviter_avatar, inviter.remark AS inviter_description FROM sd_proofing_invitations inv LEFT JOIN sys_user inviter ON inv.inviter_user_id = inviter.user_id WHERE inv.invitee_user_id = #{merchantId}
AND inv.status = #{status}
ORDER BY inv.created_at DESC

SELECT COUNT(*)
FROM sd_proofing_invitations inv
WHERE inv.invitee_user_id = #{merchantId}

    AND inv.status = #{status}
